// 📁 src/utils/api.js
import axios from "axios";

const api = axios.create({
  baseURL: "/backend",
  withCredentials: true,
  timeout: 20000,
});

api.interceptors.request.use((config) => {
  if (!config.headers?.Authorization) {
    const t = localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");
    if (t) config.headers.Authorization = `Bearer ${t}`;
  }
  return config; // ✅ pas 'cfg'
});

// Gestion centralisée des erreurs
api.interceptors.response.use(
  (r) => r,
  (err) => {
    const status = err?.response?.status;
    // Log utile pour éviter l'écran blanc silencieux
    console.error(
      "API error:",
      status,
      err?.config?.method?.toUpperCase(),
      err?.config?.url,
      err?.response?.data
    );

    if (status === 401 || status === 403) {
      localStorage.removeItem("adminToken");
      sessionStorage.removeItem("adminToken");
      // Décommente si tu veux renvoyer direct vers le login :
      // window.location.assign("/admin/login");
    }
    return Promise.reject(err);
  }
);

export const apiBase = "/backend";
export const imgUrl = (p) => (p?.startsWith("http") ? p : `${apiBase}/${p}`);
export default api;
